"use client";
import { ScrollAreaList } from "@/components/ui/scroll-area";

import * as React from "react";
import { cn } from "@/lib/utils";
import {
  controlRadiusStyle,
  type ControlAppearanceProps,
} from "@/lib/cojeev/control-appearance";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
  ItemAdornment,
  type ItemAdornmentValue,
} from "@/components/ui/item-adornment";
import { StateChevron } from "@/components/ui/animated-icon";
import { Icon } from "@/components/ui/icon";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Popover,
  PopoverAnchor,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";

export type MultiSelectOption = {
  /** Stable, unique value submitted with the form. */
  value: string;
  label: string;
  /** A disabled option cannot be selected or removed. */
  disabled?: boolean;
  adornment?: ItemAdornmentValue;
};

export type MultiSelectProps = ControlAppearanceProps & {
  /** Tokens are individually removable; summary is compact; checklist stays open. */
  presentation?: "tokens" | "summary" | "checklist";
  /** Visible accessible label for the trigger and its choices. */
  label: string;
  options: readonly MultiSelectOption[];
  /** Per-option adornments take precedence over this shared default. */
  adornment?: ItemAdornmentValue;
  /** Controlled selected values. Values absent from options remain removable. */
  value?: readonly string[];
  /** Initial selection when value is omitted. */
  defaultValue?: readonly string[];
  onValueChange?: (value: string[]) => void;
  /** Submits one hidden form entry per selected value. */
  name?: string;
  id?: string;
  disabled?: boolean;
  description?: string;
  /** Sets the trigger's invalid state and announces the error. */
  error?: string;
  placeholder?: string;
  searchPlaceholder?: string;
  emptyMessage?: string;
  noResultsMessage?: string;
  className?: string;
};

const unique = (values: readonly string[]) => [...new Set(values)];

export function MultiSelect({
  presentation = "tokens",
  radius,
  appearance,
  label,
  options,
  adornment = "auto",
  value,
  defaultValue = [],
  onValueChange,
  name,
  id,
  disabled = false,
  description,
  error,
  placeholder = "Choose options",
  searchPlaceholder = "Search options…",
  emptyMessage = "No options available.",
  noResultsMessage = "No matching options.",
  className,
}: MultiSelectProps) {
  const generatedId = React.useId();
  const controlId = id ?? `multi-select-${generatedId}`;
  const [internalValue, setInternalValue] = React.useState(() =>
    unique(defaultValue),
  );
  const [popover, setPopover] = React.useState({
    open: false,
    disabled,
    presentation,
  });
  const [query, setQuery] = React.useState("");
  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const searchRef = React.useRef<HTMLInputElement>(null);
  const rootRef = React.useRef<HTMLDivElement>(null);
  const choicesRef = React.useRef<HTMLDivElement>(null);
  const resetting = React.useRef(false);
  const selected = unique(value ?? internalValue);
  const indexed = [
    ...new Map(options.map((option) => [option.value, option])).values(),
  ];
  const selectedSet = new Set(selected);
  const term = query.trim().toLocaleLowerCase();
  const filtered = indexed.filter((option) =>
    option.label.toLocaleLowerCase().includes(term),
  );
  // Disabling a field closes it; re-enabling must not reopen a stale popup.
  if (popover.disabled !== disabled || popover.presentation !== presentation) {
    setPopover({ open: false, disabled, presentation });
    if (query) setQuery("");
  }
  React.useEffect(() => {
    const form = rootRef.current?.closest("form");
    if (!form) return;
    let resetTimer: ReturnType<typeof setTimeout> | undefined;
    // Child checkbox primitives also listen for reset. The collection owns
    // reset atomically, after the caller has had a chance to prevent it.
    const reset = (event: Event) => {
      resetting.current = true;
      clearTimeout(resetTimer);
      // A microtask may run between native event listeners. Defer beyond the
      // entire reset dispatch so a bubbling React handler can prevent it.
      resetTimer = setTimeout(() => {
        if (!event.defaultPrevented && value === undefined)
          setInternalValue(unique(defaultValue));
        resetting.current = false;
      }, 0);
    };
    form.addEventListener("reset", reset, true);
    return () => {
      form.removeEventListener("reset", reset, true);
      clearTimeout(resetTimer);
      resetting.current = false;
    };
  }, [defaultValue, value]);
  const descriptions = [
    description && `${controlId}-description`,
    error && `${controlId}-error`,
    `${controlId}-status`,
  ]
    .filter(Boolean)
    .join(" ");

  const change = (next: string[]) => {
    if (disabled || resetting.current) return;
    if (value === undefined) setInternalValue(next);
    onValueChange?.(next);
  };
  const toggle = (option: MultiSelectOption, checked: boolean) => {
    if (disabled || option.disabled) return;
    if (checked === selectedSet.has(option.value)) return;
    change(
      selectedSet.has(option.value)
        ? selected.filter((item) => item !== option.value)
        : [...selected, option.value],
    );
  };
  const changeOpen = (next: boolean) => {
    setPopover({ open: next && !disabled, disabled, presentation });
    if (!next) setQuery("");
  };
  const focusChoice = (index: number) => {
    const choices = choicesRef.current?.querySelectorAll<HTMLButtonElement>(
      '[role="checkbox"]:not(:disabled)',
    );
    if (choices?.length)
      choices[(index + choices.length) % choices.length]?.focus();
  };
  const remove = (item: string) => {
    const index = selected.indexOf(item);
    change(selected.filter((value) => value !== item));
    requestAnimationFrame(() => {
      const buttons = rootRef.current?.querySelectorAll<HTMLButtonElement>(
        '[data-slot="multi-select-remove"]:not(:disabled)',
      );
      (
        buttons?.[Math.min(index, buttons.length - 1)] ??
        triggerRef.current ??
        searchRef.current
      )?.focus();
    });
  };

  const choices = (
    <>
      <Input
        ref={searchRef}
        id={presentation === "checklist" ? controlId : `${controlId}-search`}
        appearance={appearance}
        radius={radius}
        type="search"
        size="sm"
        disabled={disabled}
        value={query}
        onChange={(event) => setQuery(event.target.value)}
        placeholder={searchPlaceholder}
        aria-label={`Search ${label}`}
        aria-describedby={descriptions}
        aria-invalid={!!error || undefined}
        autoComplete="off"
        onKeyDown={(event) => {
          if (event.key === "ArrowDown" || event.key === "ArrowUp") {
            event.preventDefault();
            focusChoice(event.key === "ArrowDown" ? 0 : -1);
          }
          if (event.key === "Enter") event.preventDefault();
        }}
      />
      <ScrollAreaList maxHeight="min(280px,40dvh)">
        <div
          ref={choicesRef}
          data-slot="multi-select-options"
          className="v-multi-select__options"
          role="group"
          aria-label={`${label} choices`}
          onKeyDown={(event) => {
            if (!["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key))
              return;
            const choices = [
              ...(choicesRef.current?.querySelectorAll<HTMLButtonElement>(
                '[role="checkbox"]:not(:disabled)',
              ) ?? []),
            ];
            const current = choices.indexOf(event.target as HTMLButtonElement);
            if (current < 0) return;
            event.preventDefault();
            focusChoice(
              event.key === "Home"
                ? 0
                : event.key === "End"
                  ? -1
                  : current + (event.key === "ArrowDown" ? 1 : -1),
            );
          }}
        >
          {filtered.map((option) => {
            const optionId = `${controlId}-option-${indexed.indexOf(option)}`;
            return (
              <div
                key={option.value}
                className="v-multi-select__option"
                data-disabled={option.disabled || undefined}
                data-selected={selectedSet.has(option.value) || undefined}
              >
                <Checkbox
                  id={optionId}
                  checked={selectedSet.has(option.value)}
                  disabled={disabled || option.disabled}
                  onCheckedChange={(next) => toggle(option, next === true)}
                />
                <label htmlFor={optionId}>
                  <ItemAdornment
                    identity={option.value}
                    value={option.adornment ?? adornment}
                  />
                  <span>{option.label}</span>
                </label>
              </div>
            );
          })}
          {!filtered.length && (
            <p className="v-multi-select__empty" role="status">
              {indexed.length ? noResultsMessage : emptyMessage}
            </p>
          )}
        </div>
      </ScrollAreaList>
      {presentation !== "tokens" &&
        selected.some(
          (item) => !indexed.some((option) => option.value === item),
        ) && (
          <div
            className="v-multi-select__unavailable"
            role="group"
            aria-label="Unavailable selections"
          >
            <p className="v-multi-select__hint">
              No longer in this list. Kept until you remove them.
            </p>
            {selected
              .filter(
                (item) => !indexed.some((option) => option.value === item),
              )
              .map((item) => (
                <Button
                  key={item}
                  data-stable-hit
                  data-slot="multi-select-remove"
                  variant="outline"
                  disabled={disabled}
                  aria-label={`Remove ${item}`}
                  onClick={() => remove(item)}
                >
                  {item}
                  <Icon name="x" size="sm" />
                </Button>
              ))}
          </div>
        )}
      <p className="v-multi-select__hint">
        {presentation === "checklist"
          ? `${selected.length} selected · Search or use the arrow keys to find an option.`
          : "Choose any number. Escape closes the list."}
      </p>
    </>
  );
  const summary = selected.map(
    (item) => indexed.find((option) => option.value === item)?.label ?? item,
  );
  return (
    <div
      ref={rootRef}
      data-slot="multi-select"
      data-presentation={presentation}
      data-appearance={appearance}
      style={controlRadiusStyle(radius)}
      data-disabled={disabled || undefined}
      data-invalid={!!error || undefined}
      className={cn("v-multi-select", className)}
    >
      <Label id={`${controlId}-label`} htmlFor={controlId} size="sm">
        {label}
      </Label>
      {presentation === "checklist" ? (
        <div className="v-multi-select__checklist">{choices}</div>
      ) : (
        <Popover open={popover.open && !disabled} onOpenChange={changeOpen}>
          <PopoverAnchor asChild>
            <div>
              <PopoverTrigger asChild>
                <Button
                  ref={triggerRef}
                  id={controlId}
                  data-stable-hit
                  data-appearance={appearance}
                  variant="outline"
                  disabled={disabled}
                  aria-labelledby={`${controlId}-label`}
                  aria-describedby={descriptions}
                  aria-invalid={!!error || undefined}
                  className="v-multi-select__trigger"
                >
                  <span className="v-multi-select__value">
                    {selected.length ? (
                      presentation === "summary" ? (
                        <>
                          <span>
                            {summary.slice(0, 2).join(", ")}
                            {summary.length > 2
                              ? ` +${summary.length - 2}`
                              : ""}
                          </span>
                          <small>
                            {selected.length} selected · Edit selection
                          </small>
                        </>
                      ) : (
                        `${selected.length} selected`
                      )
                    ) : (
                      placeholder
                    )}
                  </span>
                  <StateChevron open={popover.open && !disabled} />
                </Button>
              </PopoverTrigger>
            </div>
          </PopoverAnchor>
          <PopoverContent
            className="v-multi-select__popover"
            aria-labelledby={`${controlId}-label`}
            onOpenAutoFocus={(event) => {
              event.preventDefault();
              searchRef.current?.focus();
            }}
          >
            {choices}
          </PopoverContent>
        </Popover>
      )}
      {presentation === "tokens" && selected.length > 0 && (
        <ul className="v-multi-select__tokens" aria-label={`Selected ${label}`}>
          {selected.map((item) => {
            const option = indexed.find((option) => option.value === item);
            const text = option?.label ?? item;
            return (
              <li key={item}>
                <Badge size="sm" className="v-multi-select__token">
                  <span className="v-multi-select__token-label">{text}</span>
                  <Button
                    data-stable-hit
                    data-slot="multi-select-remove"
                    variant="ghost"
                    size="sm"
                    className="v-multi-select__remove"
                    aria-label={`Remove ${text}`}
                    disabled={disabled || option?.disabled}
                    onClick={() => remove(item)}
                  >
                    <Icon name="x" aria-hidden="true" />
                  </Button>
                </Badge>
              </li>
            );
          })}
        </ul>
      )}
      {description && (
        <p
          id={`${controlId}-description`}
          className="v-multi-select__description"
        >
          {description}
        </p>
      )}
      {error && (
        <p
          id={`${controlId}-error`}
          className="v-multi-select__error"
          role="alert"
        >
          {error}
        </p>
      )}
      <span id={`${controlId}-status`} className="v-sr" role="status">
        {selected.length} selected.
      </span>
      {name &&
        selected.map((item) => (
          <input
            key={item}
            type="hidden"
            name={name}
            value={item}
            disabled={disabled}
          />
        ))}
    </div>
  );
}

@layer cojeev-states {
.v-multi-select { display:grid; gap:10px; min-width:0; width:100%; }
.v-multi-select .v-multi-select__trigger { width:100%; min-height:44px; height:auto; padding:12px 16px; justify-content:space-between; gap:12px; text-align:start; }
.v-multi-select__trigger > span { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.v-multi-select__trigger > .v-icon { flex:none; width:18px; height:18px; }
.v-multi-select[data-invalid] .v-multi-select__trigger { box-shadow:inset 0 0 0 1px var(--v-danger); }
.v-multi-select[data-disabled] { opacity:.6; }
.v-multi-select__popover.v-popover { width:var(--radix-popover-trigger-width); min-width:min(260px,calc(100vw - 32px)); max-width:calc(100vw - 32px); padding:12px; display:grid; gap:10px; }
.v-multi-select__options { display:grid; gap:4px; min-width:0; overscroll-behavior:contain; }
.v-multi-select__option { display:flex; align-items:center; gap:10px; min-height:42px; padding:4px 8px; border-radius:var(--r-sm); }
.v-multi-select__option:hover:not([data-disabled]) { background:var(--v-beige); }
.v-multi-select__option > label { flex:1; min-width:0; padding-block:6px; font-size:var(--fs-control); line-height:1.4; cursor:pointer; overflow-wrap:anywhere; }
.v-multi-select__option[data-disabled] { opacity:.5; }
.v-multi-select__option[data-disabled] > label { cursor:not-allowed; }
.v-multi-select__option:focus-within { outline:2px solid var(--ring); outline-offset:-2px; }
.v-multi-select__tokens { list-style:none; display:flex; flex-wrap:wrap; gap:6px; margin:0; padding:0; min-width:0; }
.v-multi-select__tokens > li { min-width:0; max-width:100%; }
.v-multi-select .v-multi-select__token { min-height:32px; height:auto; max-width:100%; padding:3px 4px 3px 10px; gap:6px; }
.v-multi-select__token-label { min-width:0; overflow-wrap:anywhere; white-space:normal; line-height:1.3; }
.v-multi-select .v-multi-select__remove { width:44px; min-width:44px; height:44px; padding:0; flex:none; }
.v-multi-select__remove > .v-icon { width:14px; height:14px; }
.v-multi-select__description, .v-multi-select__error, .v-multi-select__hint, .v-multi-select__empty { margin:0; font-size:var(--fs-meta); line-height:1.5; }
.v-multi-select__description, .v-multi-select__hint, .v-multi-select__empty { color:var(--v-text-2); }
.v-multi-select__error { color:var(--v-danger-ink); }
.v-multi-select__empty { padding:16px 8px; text-align:center; }
@media (prefers-reduced-motion:reduce) { .v-multi-select *, .v-multi-select__popover * { transition-duration:0s; animation-duration:0s; } }

.v-multi-select__option > label { display:flex; flex:1; align-items:center; gap:10px; min-width:0; }
.v-multi-select__option > label > span:not(.v-item-adornment) { min-width:0; overflow-wrap:anywhere; }
.v-multi-select__option { min-height:46px; }
.v-multi-select__option:active:not([data-disabled]) { background:var(--v-pink-soft); color:var(--v-text); }
.v-multi-select__checklist { display:grid; gap:12px; min-width:0; padding:14px; border:1px solid var(--v-edge); border-radius:min(var(--v-control-radius,20px),20px); background:var(--v-canvas); }
.v-multi-select[data-appearance="inset"] .v-multi-select__checklist { background:var(--v-beige); border-color:transparent; box-shadow:inset 0 1px 2px color-mix(in oklab,var(--v-text) 12%,transparent); }
.v-multi-select[data-appearance="editorial"] .v-multi-select__checklist { border:0; border-radius:0; padding:0; background:transparent; }
.v-multi-select__trigger > .v-multi-select__value { display:grid; gap:3px; min-width:0; white-space:normal; }
.v-multi-select__value > span { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.v-multi-select__value > small { font-size:12px; color:var(--v-text-2); line-height:1.4; }
.v-multi-select[data-invalid] .v-multi-select__checklist { outline:2px solid var(--v-danger-ink); outline-offset:2px; }
.v-multi-select__option[data-selected] { background:var(--v-pink-soft); }
.v-multi-select__unavailable { display:flex; flex-wrap:wrap; gap:8px; min-width:0; }
.v-multi-select__unavailable > p { flex-basis:100%; }
.v-multi-select__unavailable > .v-btn { min-height:44px; max-width:100%; white-space:normal; overflow-wrap:anywhere; }

}

@layer cojeev-states {
/* One inherited corner contract, with a readable cap for multiline/native fields. */
:is(.v-input,.v-igroup,.v-select,.v-native,.v-number-input,.v-btn) {
  border-radius: var(--v-control-radius, var(--r-pill));
}
:is(.v-textarea,.v-composer,.v-native,.v-multi-select__trigger) {
  border-radius: min(var(--v-control-radius, 20px), 20px);
}
.v-btn[data-control-shape="card"] { border-radius: 12px; }
.v-btn[data-control-shape="pill"] { border-radius: var(--r-pill); }

/* A Field can own the treatment for its immediate shell; explicit child paint wins. */
:root .v-native[data-appearance] { padding-inline-end:40px; }
:root .v-native[data-appearance][size]:not([size="1"]) { padding-inline:8px; }
[data-slot="field"][data-appearance="contour"] { --v-field-face: var(--v-canvas); }
:root [data-appearance="contour"]:is(.v-input,.v-igroup,.v-textarea,.v-native,.v-select,.v-number-input,.v-multi-select__trigger),
:root [data-slot="field"][data-appearance="contour"] :is(.v-input,.v-igroup,.v-textarea):not([data-appearance]) {
  background-color: var(--v-canvas);
  color: var(--v-text);
  box-shadow: inset 0 0 0 1px var(--v-edge);
}
:root [data-appearance="editorial"]:is(.v-input,.v-igroup,.v-textarea,.v-native,.v-select,.v-number-input,.v-multi-select__trigger),
:root [data-slot="field"][data-appearance="editorial"] :is(.v-input,.v-igroup,.v-textarea):not([data-appearance]) {
  border-radius: 0;
  background-color: transparent;
  color: var(--v-text);
  box-shadow: inset 0 -1px 0 var(--v-edge);
  padding-inline: 2px;
}
:root [data-slot="field"][data-appearance="inset"] {
  padding: 14px 16px;
  border-radius: min(var(--v-control-radius, 20px), 20px);
  background: var(--v-beige);
  color: var(--v-text);
  box-shadow: inset 0 1px 2px color-mix(in oklab, var(--v-text) 9%, transparent);
  gap: 6px;
}
:root [data-appearance="inset"]:is(.v-input,.v-igroup,.v-textarea,.v-native,.v-select,.v-number-input,.v-multi-select__trigger) {
  background-color: var(--v-beige);
  color: var(--v-text);
  box-shadow: inset 0 1px 2px color-mix(in oklab, var(--v-text) 12%, transparent);
}
:root [data-slot="field"][data-appearance="inset"] :is(.v-input,.v-igroup,.v-textarea):not([data-appearance]) {
  background: transparent;
  box-shadow: none;
  padding-inline: 0;
}
:root [data-slot="field"][data-appearance="inset"] [data-slot="field-label"] { color: var(--v-text-2); }
:root [data-slot="field"][data-appearance="inset"]:focus-within { outline: 2px solid var(--v-brand); outline-offset: 2px; }
:root [data-appearance]:is(.v-input,.v-igroup,.v-textarea,.v-native,.v-select,.v-number-input,.v-multi-select__trigger):focus-within,
:root [data-slot="field"][data-appearance] :is(.v-input,.v-igroup,.v-textarea):focus-within {
  outline: 2px solid var(--v-brand);
  outline-offset: 3px;
}
:root [data-slot="field"][data-appearance="inset"] :is(.v-input,.v-igroup,.v-textarea):focus-within { outline: none; }
:root [data-appearance]:is(.v-input,.v-igroup,.v-textarea,.v-native,.v-select,.v-number-input,.v-multi-select__trigger):is(:disabled,[data-disabled="true"],:has(input:disabled)),
:root [data-slot="field"][data-appearance] :is(.v-input,.v-igroup,.v-textarea):is(:disabled,:has(input:disabled)) {
  background: var(--v-disabled-face);
  color: var(--v-disabled-ink);
  box-shadow: inset 0 0 0 1px var(--v-disabled-edge);
  cursor: not-allowed;
}
:root [data-slot="field"][data-appearance][data-state="error"],
:root [data-appearance]:is(.v-input,.v-igroup,.v-textarea,.v-native,.v-select,.v-number-input,.v-multi-select__trigger):is([aria-invalid="true"],[data-invalid="true"],:has([aria-invalid="true"])) {
  outline: 2px solid var(--v-danger-fill);
  outline-offset: 3px;
}
:root [data-slot="field"][data-appearance][data-state="error"] [role="alert"] { color: var(--v-danger-ink); }

.v-form-example { display: grid; gap: 20px; width: 100%; min-width: 0; max-width: 480px; margin-inline: auto; }
.v-form-example__intro { display: grid; gap: 5px; }
.v-form-example__intro strong { font-family: var(--font-display, inherit); font-size: 22px; font-weight: 500; }
.v-form-example__intro p { margin: 0; color: var(--v-text-2); font-size: 13px; line-height: 1.5; }
.v-form-example__status { min-height: 1.5em; margin: 0; font-size: 12px; color: var(--v-text-2); overflow-wrap: anywhere; }
.v-form-example__footer { display: flex; gap: 10px; align-items: center; justify-content: space-between; }

/* Composer owns one surface, while the actual textarea keeps native editing. */
:root .v-composer[data-appearance] { border-radius:min(var(--v-control-radius,20px),20px); background:var(--v-canvas); color:var(--v-text); box-shadow:inset 0 0 0 1px var(--v-edge); }
:root .v-composer[data-appearance="inset"] { background:var(--v-beige); box-shadow:inset 0 1px 2px color-mix(in oklab,var(--v-text) 12%,transparent); }
:root .v-composer[data-appearance="editorial"] { border-radius:0; background:transparent; box-shadow:inset 0 -1px 0 var(--v-edge); }
:root .v-composer[data-appearance] .v-textarea:is(:focus,:hover,:not(:focus)) { background:transparent; box-shadow:none; outline:0; border-radius:0; resize:vertical; }
:root .v-composer[data-appearance] .v-textarea-scroll > textarea { padding-inline-end:30px; }
:root [data-slot="field"][data-appearance] [data-slot="input-group"] .v-textarea { background:transparent; box-shadow:none; outline:0; border:0; border-radius:0; }
:root .v-composer[data-appearance]:focus-within { outline:2px solid var(--v-brand); outline-offset:3px; }
:root [data-slot="field"][data-appearance="inset"] .v-composer[data-appearance] { background:transparent; box-shadow:none; outline:0; }
.v-form-example[data-form-example="field"] { max-width:600px; }
.v-form-example [data-slot="field-label"] { font-size:14px; line-height:1.5; }
.v-form-example [data-slot="field-description"] { font-size:13px; margin:0; }
.v-form-example__footer > .v-btn, .v-form-example [data-slot="textarea-composer-bar"] > .v-btn { min-height:44px; }
.v-form-example [data-slot="textarea-composer-bar"] { justify-content:space-between; flex-wrap:wrap; gap:12px; padding:10px 12px; border-top:1px solid var(--v-border); }
.v-form-example__allowance { height:4px; border-radius:4px; overflow:hidden; background:var(--v-beige); margin-top:-8px; }
.v-form-example__allowance > span { display:block; height:100%; max-width:100%; border-radius:inherit; background:var(--v-blue-deep); }
.v-form-example__label-row { display:flex; align-items:baseline; flex-wrap:wrap; gap:8px; justify-content:space-between; }
.v-form-example__label-row > span { font-size:12px; color:var(--v-text-2); }
.v-form-example__hint { margin:0; color:var(--v-text-2); font-size:13px; line-height:1.5; }
/* Editorial draws only the focus edge: no moving caret, label or hit area. */
:root [data-appearance="editorial"]:is(.v-input,.v-igroup,.v-textarea,.v-composer),
:root [data-slot="field"][data-appearance="editorial"] :is(.v-input,.v-igroup,.v-textarea):not([data-appearance]) {
  background-image:linear-gradient(var(--v-brand),var(--v-brand)); background-repeat:no-repeat; background-position:left bottom; background-size:0% 2px;
  transition:background-size var(--t-micro) var(--enter);
}
:root [data-appearance="editorial"]:is(.v-input,.v-igroup,.v-textarea,.v-composer):focus-within,
:root [data-slot="field"][data-appearance="editorial"] :is(.v-input,.v-igroup,.v-textarea):focus-within { background-size:100% 2px; outline:0; }
@media(prefers-reduced-motion:reduce) { :root [data-slot="field"] :is(.v-input,.v-igroup,.v-textarea,.v-composer) { transition:none; } }

